import app from 'flarum/admin/app';
function url(path) {
  return `${app.forum.attribute('apiUrl')}/${path}`;
}
export function orderTours(ids) {
  return app.request({
    method: 'POST',
    url: url('tour-guide-tours/order'),
    body: {
      order: ids
    }
  });
}
export function orderSteps(tour, ids) {
  return app.request({
    method: 'POST',
    url: url(`tour-guide-tours/${tour.id()}/steps/order`),
    body: {
      order: ids
    }
  });
}
export function duplicateTour(tour) {
  return app.request({
    method: 'POST',
    url: url(`tour-guide-tours/${tour.id()}/duplicate`),
    params: {
      include: 'steps,groups'
    }
  }).then(payload => app.store.pushPayload(payload));
}
export function duplicateStep(step) {
  return app.request({
    method: 'POST',
    url: url(`tour-guide-steps/${step.id()}/duplicate`)
  }).then(payload => app.store.pushPayload(payload));
}
export function fetchStats(tour) {
  return app.request({
    method: 'GET',
    url: url(`tour-guide-tours/${tour.id()}/stats`)
  }).then(document => document.meta);
}
export function exportTour(tour) {
  return app.request({
    method: 'GET',
    url: url(`tour-guide-tours/${tour.id()}/export`)
  }).then(document => {
    const link = window.document.createElement('a');
    link.href = URL.createObjectURL(new Blob([JSON.stringify(document.meta, null, 2)], {
      type: 'application/json'
    }));
    link.download = `tour-${tour.key()}.json`;
    link.click();
    URL.revokeObjectURL(link.href);
  });
}
export function importTour() {
  return new Promise(resolve => {
    const input = window.document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json,.json';
    input.onchange = async () => {
      const file = input.files?.[0];
      if (!file) return resolve(null);
      let body;
      try {
        body = JSON.parse(await file.text());
      } catch {
        app.alerts.show({
          type: 'error'
        }, app.translator.trans('datlechin-simple-tour-guide.admin.tours.import_invalid'));
        return resolve(null);
      }
      app.request({
        method: 'POST',
        url: url('tour-guide-tours/import'),
        body,
        params: {
          include: 'steps,groups'
        }
      }).then(payload => {
        app.alerts.show({
          type: 'success'
        }, app.translator.trans('datlechin-simple-tour-guide.admin.tours.import_done'));
        resolve(app.store.pushPayload(payload));
      }, () => resolve(null));
    };
    input.click();
  });
}
flarum.reg.add('datlechin-simple-tour-guide', 'admin/utils/tourApi', { orderTours: orderTours,orderSteps: orderSteps,duplicateTour: duplicateTour,duplicateStep: duplicateStep,fetchStats: fetchStats,exportTour: exportTour,importTour: importTour, });