import Model from 'flarum/common/Model';
export default class TourStep extends Model {
  title() {
    return Model.attribute('title').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  localizedTitle() {
    return Model.attribute('localizedTitle').call(this);
  }
  descriptionHtml() {
    return Model.attribute('descriptionHtml').call(this);
  }
  target() {
    return Model.attribute('target').call(this);
  }
  placement() {
    return Model.attribute('placement').call(this);
  }
  devices() {
    return Model.attribute('devices').call(this);
  }
  isEnabled() {
    return Model.attribute('isEnabled').call(this);
  }
  clicksTarget() {
    return Model.attribute('clicksTarget').call(this);
  }
  advanceOnClick() {
    return Model.attribute('advanceOnClick').call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  translations() {
    const value = Model.attribute('translations').call(this);

    // PHP serializes an empty map as [].
    return Array.isArray(value) || !value ? {} : value;
  }
  tour() {
    return Model.hasOne('tour').call(this);
  }
}
flarum.reg.add('datlechin-simple-tour-guide', 'common/models/TourStep', TourStep);