import app from 'flarum/admin/app';
import Button from 'flarum/common/components/Button';
export function applyOrder(models, ids, save) {
  const before = models.map(model => [model, model.position()]);
  ids.forEach((id, position) => models.find(model => model.id() === id)?.pushAttributes({
    position
  }));
  save(ids).catch(() => {
    before.forEach(_ref => {
      let [model, position] = _ref;
      return model.pushAttributes({
        position
      });
    });
    m.redraw();
  });
  m.redraw();
}

// A keyboard cannot drag, so each row's menu can move it too.
export function moveButton(models, model, delta, save) {
  const ids = models.map(other => other.id());
  const from = ids.indexOf(model.id());
  const to = from + delta;
  return m(Button, {
    icon: delta < 0 ? 'fas fa-arrow-up' : 'fas fa-arrow-down',
    disabled: to < 0 || to >= ids.length,
    onclick: () => {
      ids.splice(to, 0, ...ids.splice(from, 1));
      applyOrder(models, ids, save);
    }
  }, delta < 0 ? app.translator.trans('datlechin-simple-tour-guide.admin.move_up') : app.translator.trans('datlechin-simple-tour-guide.admin.move_down'));
}
flarum.reg.add('datlechin-simple-tour-guide', 'admin/utils/order', { applyOrder: applyOrder,moveButton: moveButton, });